// Explicit section controls against original StickFactory/StraightFilament.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.lang.reflect.*;import java.awt.geom.*;
public class StickFactoryControlProbe extends KeyBuilderProcessProbe {
 final Object book;Object sheet,system,vertical,horizontal;public StickFactoryControlProbe(Book b,SortedSet<Integer>ids){super(b,ids);book=b;}
 Object section(int id,boolean v,int pos,int[][]runs)throws Exception{Class<?> orientation=Class.forName("org.audiveris.omr.run.Orientation"),run=Class.forName("org.audiveris.omr.run.Run");Object s=Class.forName("org.audiveris.omr.lag.DynamicSection").getConstructor(orientation).newInstance(v?vertical:horizontal);call(s,"setId",id);call(s,"setFirstPos",pos);for(int[] r:runs)call(s,"append",run.getConstructor(int.class,int.class).newInstance(r[0],r[1]));return s;}
 Object v(int id,int x,int y,int w,int len)throws Exception{int[][]runs=new int[w][2];for(int i=0;i<w;i++)runs[i]=new int[]{y,len};return section(id,true,x,runs);}
 Object h(int id,int x,int y,int height)throws Exception{int[][]runs=new int[height][2];for(int i=0;i<height;i++)runs[i]=new int[]{x,1};return section(id,false,y,runs);}
 String filament(Object f)throws Exception{Object basic=call(f,"getBasicLine");Line2D line=(Line2D)call(f,"getLine");Object glyph=call(f,"toGlyph",(Object)null);return "{\"members\":"+StemSeedsProbe.sectionList((Collection<?>)call(f,"getMembers"))+",\"bounds\":"+rect(call(f,"getBounds"))+",\"weight\":"+call(f,"getWeight")+",\"start\":"+StemSeedsProbe.point(call(f,"getStartPoint",vertical))+",\"stop\":"+StemSeedsProbe.point(call(f,"getStopPoint",vertical))+",\"line\":["+line.getX1()+","+line.getY1()+","+line.getX2()+","+line.getY2()+"],\"mean_distance\":"+call(f,"getMeanDistance")+",\"basic_line\":{\"a\":"+call(basic,"getA")+",\"b\":"+call(basic,"getB")+",\"c\":"+call(basic,"getC")+",\"point_count\":"+call(basic,"getNumberOfPoints")+"},\"glyph\":"+canonicalGlyph(glyph)+"}";}
 @SuppressWarnings("unchecked") String observe(String name,List<Object>vs,List<Object>hs,int thickness,int core,boolean overlap)throws Exception{
  Object index=Class.forName("org.audiveris.omr.glyph.dynamic.FilamentIndex").getConstructor(Class.forName("org.audiveris.omr.sheet.Sheet")).newInstance(sheet);Object factory=Class.forName("org.audiveris.omr.glyph.dynamic.StickFactory").getConstructor(Class.forName("org.audiveris.omr.run.Orientation"),Class.forName("org.audiveris.omr.sheet.SystemInfo"),Class.forName("org.audiveris.omr.glyph.dynamic.FilamentIndex"),java.util.function.Predicate.class,int.class,int.class,double.class).newInstance(vertical,system,index,null,thickness,core,.4);
  String inputV=StemSeedsProbe.sectionList(vs),inputH=StemSeedsProbe.sectionList(hs);Comparator<Object> full=(Comparator<Object>)Class.forName("org.audiveris.omr.lag.Section").getField("byFullPosition").get(null);boolean sorted=true;for(int i=1;i<vs.size();i++)if(full.compare(vs.get(i-1),vs.get(i))>0)sorted=false;
  List<?> candidates=(List<?>)call(factory,"retrieveSticks",new ArrayList<>(vs),new ArrayList<>(hs));List<String> outputs=new ArrayList<>();for(Object f:candidates)outputs.add(filament(f));List<String> graph=new ArrayList<>();for(Object linked:(List<?>)get(factory,"allSections")){List<Integer> sources=new ArrayList<>(),targets=new ArrayList<>();for(Object s:(List<?>)call(linked,"getSources"))sources.add((Integer)call(s,"getId"));for(Object s:(List<?>)call(linked,"getTargets"))targets.add((Integer)call(s,"getId"));graph.add("{\"id\":"+call(linked,"getId")+",\"processed\":"+call(linked,"isProcessed")+",\"sources_after_retrieve\":"+sources+",\"targets_after_retrieve\":"+targets+"}");}
  return "{\"name\":"+q(name)+",\"overlapping_input_sections\":"+overlap+",\"input_sorted_full_position\":"+sorted+",\"max_thickness\":"+thickness+",\"min_core\":"+core+",\"min_side_ratio\":0.4,\"vertical\":"+inputV+",\"horizontal\":"+inputH+",\"candidates\":["+String.join(",",outputs)+"],\"linked_sections_after\":["+String.join(",",graph)+"]}";
 }
 String fit(String name,List<Object>parts)throws Exception{Object f=Class.forName("org.audiveris.omr.glyph.dynamic.StraightFilament").getConstructor(int.class).newInstance(call(call(sheet,"getScale"),"getInterline"));for(Object s:parts)call(f,"addSection",s);List<String> samples=new ArrayList<>();double[] ys={99,100,110,124,125,126,140,149,150};for(double y:ys){Object p=call(f,"getStartPoint",vertical),q=call(f,"getStopPoint",vertical);Line2D l=new Line2D.Double((Point2D)p,(Point2D)q);double x=(Double)Class.forName("org.audiveris.omr.math.LineUtil").getMethod("xAtY",Line2D.class,double.class).invoke(null,l,y);samples.add("{\"y\":"+y+",\"x\":"+x+",\"ceil\":"+(int)Math.ceil(x)+",\"floor\":"+(int)Math.floor(x)+"}");}return "{\"name\":"+q(name)+",\"input_sections\":"+StemSeedsProbe.sectionList(parts)+",\"filament\":"+filament(f)+",\"original_lineutil_samples\":["+String.join(",",samples)+"]}";}
 public void process(){try{
  sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");call(Class.forName("org.audiveris.omr.sheet.grid.GridStep").getConstructor().newInstance(),"doit",sheet);system=((List<?>)call(sheet,"getSystems")).get(0);Class<?> o=Class.forName("org.audiveris.omr.run.Orientation");vertical=o.getField("VERTICAL").get(null);horizontal=o.getField("HORIZONTAL").get(null);List<String> cases=new ArrayList<>(),fits=new ArrayList<>();
  cases.add(observe("empty",new ArrayList<>(),new ArrayList<>(),3,24,false));for(int length:new int[]{23,24,25})cases.add(observe("core-length-"+length,List.of(v(1,200,100,1,length)),List.of(),3,24,false));for(int width:new int[]{2,3,4})cases.add(observe("core-thickness-"+width,List.of(v(1,200,100,width,30)),List.of(),3,24,false));
  cases.add(observe("equal-length-sorted",List.of(v(11,200,70,1,30),v(2,200,120,1,30),v(7,200,170,1,30)),List.of(),3,24,false));cases.add(observe("equal-length-explicit-reversed",List.of(v(7,200,170,1,30),v(2,200,120,1,30),v(11,200,70,1,30)),List.of(),3,24,false));
  for(int side:new int[]{19,20,21})cases.add(observe("side-ratio-right-"+side+"-of-50",List.of(v(1,200,100,1,50),v(2,201,100,2,side)),List.of(),3,24,false));for(int side:new int[]{19,20,21})cases.add(observe("side-ratio-left-"+side+"-of-50",List.of(v(2,198,100,2,side),v(1,200,100,1,50)),List.of(),3,24,false));
  for(int max:new int[]{2,3})cases.add(observe("combined-thickness-limit-"+max,List.of(v(1,200,100,1,50),v(2,201,100,2,21)),List.of(),max,24,false));
  cases.add(observe("single-column-sticker-below-ratio",List.of(v(1,200,100,1,50),v(2,201,100,1,1)),List.of(),3,24,false));
  for(boolean reverse:new boolean[]{false,true}){List<Object>inputs=new ArrayList<>();inputs.add(v(1,200,100,1,50));if(reverse){inputs.add(v(3,201,100,2,20));inputs.add(v(2,201,100,1,20));}else{inputs.add(v(2,201,100,1,20));inputs.add(v(3,201,100,2,20));}cases.add(observe("coordinate-tied-overlapping-neighbors-reverse-"+reverse,inputs,List.of(),3,24,true));}
  cases.add(observe("opposite-stickers-both-sides",List.of(v(1,200,100,1,50)),List.of(h(10,199,110,5),h(11,201,130,7)),3,24,false));cases.add(observe("opposite-sticker-no-touch",List.of(v(1,200,100,1,50)),List.of(h(10,198,110,5),h(11,201,150,7)),3,24,false));cases.add(observe("opposite-sticker-partial-touch",List.of(v(1,200,100,1,50)),List.of(h(10,199,98,4),h(11,201,148,4)),3,24,false));
  cases.add(observe("sloped-one-pixel-overlap",List.of(v(1,200,100,1,26),v(2,201,125,1,25)),List.of(),3,24,false));cases.add(observe("sloped-two-pixel-overlap",List.of(v(1,200,100,1,27),v(2,201,125,1,25)),List.of(),3,24,false));cases.add(observe("widening-slanted-runs",List.of(section(1,true,200,new int[][]{{100,50},{101,50},{102,50}})),List.of(),3,24,false));
  fits.add(fit("staircase-near-half",List.of(v(1,200,100,1,25),v(2,201,125,1,25))));fits.add(fit("staircase-one-row-shift",List.of(v(1,200,100,1,26),v(2,201,126,1,24))));fits.add(fit("slanted-asymmetric-multi-column",List.of(section(1,true,200,new int[][]{{100,24},{101,26}}),section(2,true,202,new int[][]{{123,25},{124,26}}))));fits.add(fit("mixed-orientation-sticker",List.of(v(1,200,100,1,50),h(10,201,120,11))));
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"controlled_input\":true,\"description\":\"Original DynamicSection/Run constructors with declared runs, fresh original FilamentIndex/StickFactory, direct untouched retrieveSticks; fit controls call original StraightFilament.addSection. Underlying sheet/system geometry comes from original GRID only. Unsorted and overlapping section inputs are explicitly labelled, not natural segmentation claims.\",\"interline\":"+call(call(sheet,"getScale"),"getInterline")+",\"sheet_width\":"+call(sheet,"getWidth")+",\"sheet_height\":"+call(sheet,"getHeight")+",\"cases\":["+String.join(",",cases)+"],\"direct_fit_cases\":["+String.join(",",fits)+"]}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
